    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Connected components of all non-background cells.
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            color = grid[r][c]
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny, nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            comps.append((color, cells))

    # Find the prominent L-shaped component and its elbow.
    marker = None
    for i, (color, cells) in enumerate(comps):
        points = set(cells)
        for r, c in points:
            vertical = any((r + d, c) in points for d in (-1, 1))
            horizontal = any((r, c + d) in points for d in (-1, 1))
            if not (vertical and horizontal):
                continue

            # The elbow has a long straight run in both axes.
            up = down = left = right = 0
            y = r - 1
            while (y, c) in points:
                up += 1
                y -= 1
            y = r + 1
            while (y, c) in points:
                down += 1
                y += 1
            x = c - 1
            while (r, x) in points:
                left += 1
                x -= 1
            x = c + 1
            while (r, x) in points:
                right += 1
                x += 1

            vlen = max(up, down)
            hlen = max(left, right)
            score = vlen + hlen
            if vlen >= 2 and hlen >= 2 and (marker is None or score > marker[0]):
                arms = []
                if up: arms.append((-1, 0))
                if down: arms.append((1, 0))
                if left: arms.append((0, -1))
                if right: arms.append((0, 1))
                # For an L, retain only the longest direction on each axis.
                arms = [(-1, 0) if up >= down else (1, 0),
                        (0, -1) if left >= right else (0, 1)]
                marker = (score, i, color, r, c, arms)

    if marker is None:
        return out

    _, marker_i, marker_color, er, ec, arms = marker

    # Select the component nearest a backward extension of either L arm.
    best = None
    for i, (color, cells) in enumerate(comps):
        if i == marker_i:
            continue
        for dr, dc in arms:
            # Search opposite the direction in which that arm extends.
            rr, cc = -dr, -dc
            for r, c in cells:
                t = (r - er) * rr + (c - ec) * cc
                if t <= 0:
                    continue
                perp = abs((r - er) * dc - (c - ec) * dr)
                key = (perp, t)
                if best is None or key < best[0]:
                    best = (key, cells)

